import type { Types } from '@fiverr-private/theme';
import type { TagProps } from '../types';

export const getCloseIconStyles = ({
    isClickable,
    variant,
    isDark,
}: {
    isClickable: boolean;
    variant: TagProps['variant'];
    isDark: boolean;
}): Types.BoxType => ({
    boxSizing: 'borderBox',
    display: 'inlineFlex',
    padding: '1',
    borderRadius: 'circle',
    outlineColor: {
        focusVisible: isDark ? 'white_10' : 'grey_1200',
    },
    outlineStyle: { focusVisible: 'solid' },
    outlineWidth: {
        focusVisible: 'md',
    },
    height: '24px',
    width: '24px',
    ...(isClickable &&
        variant === 'filled' && {
            backgroundColor: {
                default: 'transparent',
                hover: isDark ? 'white_20' : 'grey_200',
                active: isDark ? 'white_20' : 'grey_300',
            },
        }),
    ...(isClickable &&
        variant === 'outline' && {
            backgroundColor: {
                default: 'transparent',
                hover: isDark ? 'white_20' : 'grey_400',
                active: isDark ? 'white_20' : 'grey_500',
            },
        }),
});
