import React, { type MouseEvent } from 'react';
import { TimesIcon } from '@fiverr-private/visuals';
import { Box, type Types } from '@fiverr-private/theme';
import { translate } from '@fiverr-private/i18n-react';
import { useTagContext } from '../TagContext';
import { getCloseIconStyles } from './styles';

const TagCloseIcon = ({
  onClick,
  dataTrackTag = 'tag_close_icon',
  dataTrackValue,
}: {
  onClick?: Types.ContainerProps['onClick'];
  dataTrackTag?: Types.ContainerProps['dataTrackTag'];
  dataTrackValue?: Types.ContainerProps['dataTrackValue'];
}) => {
  const { clickableArea, setIsOpen, variant, hideOnClick, isDark } = useTagContext();
  const isClickable = clickableArea === 'closeButton' || clickableArea === 'multi';

  const onCloseIconClick = (e: MouseEvent<HTMLDivElement>) => {
    if (isClickable) {
      e.stopPropagation();
      onClick?.(e);

      if (hideOnClick) {
        setIsOpen(false);
      }
    }
  };

  return (
    <Box
      {...getCloseIconStyles({ isClickable, variant, isDark })}
      as={isClickable ? 'button' : 'div'}
      role={isClickable ? 'button' : undefined}
      aria-label={isClickable ? translate<string>('data_display.tag.close') : undefined}
      onClick={onCloseIconClick}
      dataTrackTag={dataTrackTag}
      dataTrackValue={dataTrackValue}
    >
      <TimesIcon size="sm" color={isDark ? 'grey_400' : 'grey_1200'} />
    </Box>
  );
};

TagCloseIcon.displayName = 'TagCloseIcon';
TagCloseIcon.id = 'TagCloseIcon';

export default TagCloseIcon;
