import React from 'react';
import { findChildByType } from '@fiverr-private/ui_utils';
import { Container } from '@fiverr-private/layout_components';
import type { TagPrefixProps } from '../types';
import { useTagContext } from '../TagContext';

const TagPrefix = ({ children, dataTrackTag = 'tag_prefix', dataTrackValue }: TagPrefixProps) => {
  const { size } = useTagContext();
  const hasAvatar = !!findChildByType(children, 'Avatar');
  const hasTagImage = !!findChildByType(children, 'TagImage');

  return (
    <Container
      style={hasAvatar || hasTagImage ? { marginLeft: size === 'md' ? '-10px' : '-8px' } : undefined}
      display="inlineFlex"
      dataTrackTag={dataTrackTag}
      dataTrackValue={dataTrackValue}
    >
      {children}
    </Container>
  );
};

TagPrefix.displayName = 'TagPrefix';

export default TagPrefix;
