import React from 'react';
import { Image } from '@fiverr-private/media';
import { useTagContext } from '../TagContext';
import type { TagImageProps } from './types';

const TagImage = ({ borderRadius = 'circle', src, dataTrackTag = 'tag_image', ...rest }: TagImageProps) => {
  const { size } = useTagContext();
  return (
    <Image
      borderRadius={borderRadius}
      src={src}
      {...rest}
      dataTrackTag={dataTrackTag}
      width={size === 'xs' ? 16 : 24}
      height={size === 'xs' ? 16 : 24}
    ></Image>
  );
};

TagImage.id = 'TagImage';
TagImage.displayName = 'TagImage';
export default TagImage;
